from pathlib import Path
p=Path(__file__).parent
images=['https://cdn.prod.website-files.com/64dfd6f3c8bff842f83e0e0e/6aad6c185e44c39a92c8e582_forgif-ezgif.com-video-to-gif-converter.gif', 'https://cdn.prod.website-files.com/64dfd6f3c8bff842f83e0e0e/6a28afbc5b93f9f574f078fc_img.png', 'https://cdn.prod.website-files.com/64dfd6f3c8bff842f83e0e0e/6900499a98c4b0479a078a50_68ed6c43cb98d7517fe48ffb6c18dbd1_red%20moment%20of%20love.png', 'https://cdn.prod.website-files.com/64dfd6f3c8bff842f83e0e0e/67ebe520d5174e0cbf16829f_Frame%203123.jpg', 'https://cdn.prod.website-files.com/64dfd6f3c8bff842f83e0e0e/67e967495a56e134f60784d7_OpenBox_Honeycomb%202.jpg']
svg=(p/'assets/logo.svg').read_text(); svg=svg[svg.index('<svg'):]; svg=svg.replace('<svg ', '<svg class="av-logo" aria-hidden="true" ' ,1)
css='''<style>
.av-work,.av-work *{box-sizing:border-box}.av-work{position:relative;isolation:isolate;width:100%;height:var(--av-height, min(800px,90svh));min-height:420px;padding-inline:clamp(28px,6vw,96px);background:transparent;display:grid;place-items:center;overflow:hidden;color:#171714}.av-work .av-mark{width:min(48%,460px);position:relative;z-index:2}.av-work .av-logo{width:100%;height:auto;display:block;overflow:visible;pointer-events:none;}.av-work .av-logo path{pointer-events:none}.av-work .av-hit{position:absolute;inset:-36px -24px;cursor:crosshair;touch-action:pan-y}.av-work .av-card{position:absolute;z-index:3;left:var(--x,50%);top:var(--y,50%);width:clamp(240px,42vw,520px);margin:0;pointer-events:none;opacity:0;transform:translate(-50%,-45%) rotate(var(--r,-5deg)) scale(.87);transition:opacity 160ms ease,transform 320ms cubic-bezier(.2,.8,.2,1);filter:drop-shadow(0 12px 20px #0002)}.av-work .av-card[data-open]{pointer-events:auto;opacity:1;transform:translate(-50%,-50%) rotate(var(--r,-5deg)) scale(1)}.av-work .av-card img{display:block;width:100%;height:auto;max-height:520px;object-fit:contain}.av-work .av-key{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);border:0;padding:0}.av-work .av-key:focus-visible{clip-path:none;width:auto;height:auto;left:50%;bottom:-48px;transform:translateX(-50%);white-space:nowrap;padding:8px 12px;background:#fff;color:#111;border:1px solid;outline-offset:4px;font:12px Arial,sans-serif}.av-work .av-hint{position:absolute;bottom:24px;left:0;width:100%;text-align:center;font:10px/1.4 Arial,sans-serif;letter-spacing:.15em;text-transform:uppercase;opacity:.45;pointer-events:none}.av-work .av-tap{display:none}@media(hover:none){.av-work .av-hover{display:none}.av-work .av-tap{display:inline}}@media(max-width:600px){.av-work{min-height:400px;height:var(--av-height,75svh)}.av-work .av-mark{width:68%}.av-work .av-card{width:72vw;max-width:380px}}.av-work .av-pixels{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;image-rendering:pixelated}@media(prefers-reduced-motion:reduce){.av-work .av-logo{animation:none;will-change:auto}.av-work .av-pixels{display:none;animation:none}.av-work .av-card{transition:none}}
</style>'''
markup='<section class="av-work" aria-label="Explore Aashita Verma’s work"><div class="av-mark">'+svg+'<a class="av-hit" href="https://www.aashitaverma.com/work" target="_top" aria-label="View all work"></a>'+''.join(f'<button class="av-key" type="button" data-project="{i}" aria-expanded="false">Preview project {i+1}</button>' for i in range(len(images)))+'</div>'+''.join(f'<figure class="av-card" data-card="{i}" style="--r:{[-7,6,-4,8,-6][i]}deg"><a href="https://www.aashitaverma.com/work" target="_top" aria-label="View work"><img src="{images[i]}" alt="Portfolio project preview {i+1}" loading="eager" draggable="false"></a></figure>' for i in range(len(images)))+'</section>'
js='''<script>
(()=>{const root=document.currentScript.previousElementSibling;const logo=root.querySelector('.av-logo');const pixels=document.createElement('canvas');pixels.className='av-pixels';pixels.setAttribute('aria-hidden','true');logo.after(pixels);const pixelImage=new Image();const reduced=matchMedia('(prefers-reduced-motion: reduce)');let pixelReady=false;let lastDraw=0;let cachedRaster;let rasterWidth=0;function drawPixels(time=0){if(!pixelReady)return;if(reduced.matches){logo.style.opacity='1';logo.style.maskImage='none';logo.style.webkitMaskImage='none';pixels.style.display='none';return}pixels.style.display='block';logo.style.opacity='1';const r=logo.getBoundingClientRect();const cols=Math.max(1,Math.round(r.width/4));const rows=Math.max(1,Math.round(cols*48/370));if(cols!==rasterWidth){rasterWidth=cols;pixels.width=cols;pixels.height=rows;const sample=document.createElement('canvas');sample.width=cols;sample.height=rows;const sampleCtx=sample.getContext('2d',{willReadFrequently:true});sampleCtx.drawImage(pixelImage,0,0,cols,rows);cachedRaster=sampleCtx.getImageData(0,0,cols,rows).data}const ctx=pixels.getContext('2d');ctx.clearRect(0,0,cols,rows);ctx.fillStyle='#000';const t=time/1000;const crisp=Array.from({length:rows},(_,y)=>Array.from({length:cols},(_,x)=>Math.sin(t*.19-x*.075-y*.045)>.05));let bands='';for(let y=0;y<rows;y++)for(let x=0;x<cols;x++)if(crisp[y][x])bands+='<rect x="'+x+'" y="'+y+'" width="1.005" height="1.005" fill="white"/>';const mask='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+cols+' '+rows+'" preserveAspectRatio="none">'+bands+'</svg>';const maskUrl='url("data:image/svg+xml,'+encodeURIComponent(mask)+'")';logo.style.maskImage=maskUrl;logo.style.webkitMaskImage=maskUrl;logo.style.maskMode='alpha';for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const letter=Math.floor(x/cols*11);const threshold=104+5*Math.sin(t*.16+letter*.7);if(cachedRaster[(y*cols+x)*4+3]>threshold){ctx.globalAlpha=crisp[y][x]?0:1;ctx.fillRect(x,y,1,1)}}}function animate(time){if(time-lastDraw>160){drawPixels(time);lastDraw=time}requestAnimationFrame(animate)}pixelImage.onload=()=>{pixelReady=true;drawPixels();new ResizeObserver(()=>{rasterWidth=0;drawPixels(performance.now())}).observe(logo);requestAnimationFrame(animate)};pixelImage.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(new XMLSerializer().serializeToString(logo));reduced.addEventListener('change',()=>drawPixels(performance.now()));const hit=root.querySelector('.av-hit');const paths=[...logo.querySelectorAll('path')];const cards=[...root.querySelectorAll('.av-card')];const keys=[...root.querySelectorAll('.av-key')];let active=-1;
const close=()=>{active=-1;cards.forEach(c=>c.removeAttribute('data-open'));keys.forEach(b=>b.setAttribute('aria-expanded','false'))};
function show(i,x,y){const area=root.getBoundingClientRect();const mark=logo.getBoundingClientRect();const card=cards[i];const width=card.getBoundingClientRect().width;const height=card.getBoundingClientRect().height;const px=x===undefined?mark.left-area.left+mark.width*(i+.5)/cards.length:x-area.left;const py=y===undefined?mark.top-area.top+mark.height/2:y-area.top;const clamp=(v,size,limit,pad=16)=>Math.max(size/2+pad,Math.min(limit-size/2-pad,v));card.style.setProperty('--x',clamp(px,width,area.width,Math.min(64,area.width*.08))+'px');card.style.setProperty('--y',clamp(py,height,area.height)+'px');if(active!==i){close();active=i;card.setAttribute('data-open','');keys[i].setAttribute('aria-expanded','true')}}
function preview(e){let best=0;let distance=Infinity;paths.forEach((path,i)=>{const r=path.getBoundingClientRect();const dx=Math.max(r.left-e.clientX,0,e.clientX-r.right);const dy=Math.max(r.top-e.clientY,0,e.clientY-r.bottom);const d=dx*dx+dy*dy;if(d<distance){distance=d;best=i}});show(best%cards.length,e.clientX,e.clientY)}
hit.addEventListener('pointerenter',e=>{if(e.pointerType!=='touch')preview(e)});hit.addEventListener('pointermove',e=>{if(e.pointerType!=='touch')preview(e)});hit.addEventListener('pointerleave',e=>{if(e.pointerType!=='touch'&&!e.relatedTarget?.closest('.av-card'))close()});cards.forEach(card=>card.addEventListener('pointerleave',e=>{if(!e.relatedTarget?.closest('.av-hit,.av-card'))close()}));keys.forEach((b,i)=>{b.addEventListener('focus',()=>show(i));b.addEventListener('click',()=>show(i));b.addEventListener('blur',close)});root.addEventListener('click',e=>{if(!e.target.closest('.av-mark,.av-card'))close()});root.addEventListener('keydown',e=>{if(e.key==='Escape')close()});root.addEventListener('pointerleave',close);
})();
</script>'''
embed=css+markup+js
(p/'section-source.html').write_text(embed)
(p/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Aashita Verma — Work Preview</title><style>body{margin:0;background:transparent} .av-work{--av-height:100svh}</style>'+embed+'</html>')
